run_ct36.ps1.content:
param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference = 'Stop'
$ct36Container = (docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $ct36Container.State.Status -ne 'running') { throw 'Dedicated test database is not running' }
$ct36Settings = @{}
foreach ($ct36Entry in $ct36Container.Config.Env) {
    $ct36Pair = $ct36Entry.Split('=', 2)
    $ct36Settings[$ct36Pair[0]] = $ct36Pair[1]
}
if ($ct36Settings.POSTGRES_DB -ne 'q019_agent_test' -or $ct36Settings.POSTGRES_USER -ne 'q019') { throw 'Unexpected database identity' }
if ($ct36Container.NetworkSettings.Ports.'5432/tcp'[0].HostPort -ne '55433') { throw 'Unexpected port' }
$env:Q019_TEST_DATABASE_URL = 'postgresql://q019:' + [uri]::EscapeDataString($ct36Settings.POSTGRES_PASSWORD) + '@127.0.0.1:55433/q019_agent_test?connect_timeout=5'
$env:PYTHONUTF8 = '1'
$env:PYTHONPATH = 'src'
try {
    & .venv/Scripts/python.exe .test-tmp/ct36_run.py @TrialArguments
    $ct36Exit = $LASTEXITCODE
} finally {
    Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue
    $ct36Settings.Clear()
}
exit $ct36Exit
